update content_bodies set title = '#Amami #Travel 4k 30min Korean ver', description = 'The charm of Amami Oshima '' #Amami #Travel '' 
Amami Oshima, a world natural heritage site with rich and unique culture.

 ''#Amami #Travel'' is a video where two women from Amami Oshima, living away from the island, rediscover the charm of Amami Oshima while touring tourist spots and scenic areas by rental car. 
Please make sure to refer to it before your trip to Amami Oshima.

Also, when you come to Amami Oshima, let''s share beautiful landscape photos of Amami Oshima on social media with the hashtag ''#Amami #Travel''! 

