update content_bodies set title = '遊山箱-ＹＵＳＡＮＢＡＫＯ-［Tokushima］', description = 'Tokushima has been producing lumber for a very long time.  High quality lumber processing technique of shipwrights used to serve the powerful navy of Awa-Han (feudal domain/a part of present Tokushima) greatly in the Edo Period (1603–1868), and the technique has been passed down through the generations.

A carpentry skill called Mokuhari (thin wood sheet craft) is utilized and beautiful paintwork is applied to Yusanbako.  It is a three-tiered box that used to be used as a lunch box for leisure in fields and mountains, and Doll’s Festivals.

