update content_bodies set title = 'Okayama 岡山｜JAPAN - Maniwa City! -', description = 'Beautiful traditional townscapes, a nostalgic building of a former elementary school, the lush green Hiruzen Kogen Highlands, GREENable HIRUZEN – an information facility designed by Kengo Kuma to make more people familiar with the value of sustainability. This is a one-day tour to explore the town of Maniwa and, of course, enjoy local foods!

